def compute(vars):
    cdb_yield = vars["v1"]
    treasury_yield = vars["v2"]

    if cdb_yield == 0:
        return None

    yield_difference = cdb_yield - treasury_yield
    implicit_tax_rate = yield_difference / cdb_yield

    return {
        "value": implicit_tax_rate,
        "trace": {
            "cdb_yield": cdb_yield,
            "treasury_yield": treasury_yield,
            "yield_difference": yield_difference,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
